local function _hx(s)
    local t = {}
    for i = 1, #s, 2 do
        t[#t + 1] = string.char(tonumber(s:sub(i, i + 1), 16))
    end
    return table.concat(t)
end

local function _b64(s)
    local A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local out = {}
    local acc, bits, oi = 0, 0, 0
    for i = 1, #s do
        local c = s:sub(i,i)
        if c ~= "=" then
            local v = A:find(c, 1, true)
            if v then
                v = v - 1
                acc = acc * 64 + v
                bits = bits + 6
                if bits >= 8 then
                    bits = bits - 8
                    oi = oi + 1
                    out[oi] = string.char(math.floor(acc / 2^bits) % 256)
                end
            end
        end
    end
    return table.concat(out)
end

local function _xor(data, key)
    local out = {}
    local kl = #key
    for i = 1, #data do
        local a = data:byte(i)
        local b = key:byte(((i - 1) % kl) + 1)
        local r = 0
        local p = 1
        while a > 0 or b > 0 do
            local aa = a % 2
            local bb = b % 2
            if aa ~= bb then r = r + p end
            a = math.floor(a / 2)
            b = math.floor(b / 2)
            p = p * 2
        end
        out[i] = string.char(r)
    end
    return table.concat(out)
end

local _data = _b64(table.concat(_P))
local _key = _hx(_K)
local _src = _xor(_data, _key)

local _load = loadstring or load
if type(_load) ~= "function" then
    error("This protected build requires loadstring/load support.", 0)
end

local _fn, _err = _load(_src)
if not _fn then
    error(_err or "Protected source failed to load.", 0)
end
return _fn()
